Implementation details for pointer handling:

```js
const stick = document.getElementById('joystick');
const knob = document.getElementById('stickKnob');
let stickId = null, stickVec = {x:0,y:0};
const STICK_R = 34; // max knob travel in px

function setStickFromEvent(e){
  const rect = stick.getBoundingClientRect();
  const cx = rect.left + rect.width/2, cy = rect.top + rect.height/2;
  let dx = e.clientX - cx, dy = e.clientY - cy;
  const len = Math.hypot(dx,dy);
  if(len > STICK_R){ dx = dx/len*STICK_R; dy = dy/len*STICK_R; }
  knob.style.transform = `translate(${dx}px, ${dy}px)`;
  const nx = dx/STICK_R, ny = dy/STICK_R;
  const mag = Math.hypot(nx,ny);
  const dead = 0.18;
  if(mag < dead){ stickVec.x = 0; stickVec.y = 0; }
  else {
    const scaled = Math.min(1,(mag-dead)/(1-dead));
    stickVec.x = nx/mag*scaled; stickVec.y = ny/mag*scaled;
  }
}
```

