function dash(){if(!running||player.dashCd>0)return;player.dash=.19;player.dashCd=1.15;player.invuln=Math.max(player.invuln,.23);sound(430,.08);}
function stickReset(){
  stick.x=0;stick.y=0;stick.mag=0;stick.id=null;
  stickKnob.style.transform='translate(0px,0px)';
  joystick.classList.remove('active');
}
function stickMove(e){
  const rect=joystick.getBoundingClientRect();
  let dx=e.clientX-(rect.left+rect.width/2), dy=e.clientY-(rect.top+rect.height/2);
  const len=Math.hypot(dx,dy);
  if(len>STICK_R){dx=dx/len*STICK_R;dy=dy/len*STICK_R;}
  stickKnob.style.transform=`translate(${dx.toFixed(1)}px,${dy.toFixed(1)}px)`;
  const mag=Math.min(1,len/STICK_R);
  if(mag<STICK_DEAD){stick.x=0;stick.y=0;stick.mag=0;return;}
  stick.x=dx/(len||1);stick.y=dy/(len||1);
  stick.mag=Math.min(1,(mag-STICK_DEAD)/(1-STICK_DEAD));
}
joystick.addEventListener('pointerdown',e=>{
  e.preventDefault();e.stopPropagation();
  stick.id=e.pointerId;joystick.setPointerCapture(e.pointerId);joystick.classList.add('active');
  stickMove(e);
});
joystick.addEventListener('pointermove',e=>{
  if(e.pointerId!==stick.id)return;
  e.preventDefault();stickMove(e);
});
const stickEnd=e=>{if(e.pointerId!==stick.id)return;e.preventDefault();stickReset();};
joystick.addEventListener('pointerup',stickEnd);
joystick.addEventListener('pointercancel',stickEnd);
joystick.addEventListener('lostpointercapture',()=>{if(stick.id!==null)stickReset();});
joystick.addEventListener('contextmenu',e=>e.preventDefault());
stage.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&running&&e.target===canvas)dash();});
dashBtn.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();dash();});

